package $P1.app;

import $P1.application.contact.ContactViewModel;
import $P1.application.contact.CreateContact;
import $P1.application.contact.GetContact;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/contacts")
class ContactController {

    record CreateContactRequest(String name, String email) {}

    record CreateContactResponse(UUID id) {}

    private final CreateContact createContact;
    private final GetContact getContact;

    ContactController(CreateContact createContact, GetContact getContact) {
        this.createContact = createContact;
        this.getContact = getContact;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    CreateContactResponse create(@RequestBody CreateContactRequest request) {
        var id = UUID.randomUUID();
        createContact.handle(id, request.name(), request.email());
        return new CreateContactResponse(id);
    }

    @GetMapping("/{id}")
    ResponseEntity<ContactViewModel> get(@PathVariable UUID id) {
        return getContact.handle(id).map(ResponseEntity::ok).orElseGet(() -> ResponseEntity.notFound().build());
